import{_ as e,C as o,c as C,o as l,a1 as A,G as t}from"./chunks/framework.C3Hmo1as.js";const d=JSON.parse('{"title":"大模型工具调用架构指南","description":null,"frontmatter":{"title":"大模型工具调用架构指南","description":null,"date":"2026-09-25T00:00:00.000Z","tags":["Function Call","MCP","Skill"]},"headers":[],"relativePath":"ai/llm-tool-execution-function-call-mcp-skill-architecture.md","filePath":"ai/llm-tool-execution-function-call-mcp-skill-architecture.md"}'),n={name:"ai/llm-tool-execution-function-call-mcp-skill-architecture.md"};function r(a,E,i,F,s,p){const B=o("Mermaid");return l(),C("div",null,[E[0]||(E[0]=A('<h2 id="剥开大模型的-全能-外衣-function-call、mcp-与-skill-的底层架构演进" tabindex="-1">剥开大模型的“全能”外衣：Function Call、MCP 与 Skill 的底层架构演进 <a class="header-anchor" href="#剥开大模型的-全能-外衣-function-call、mcp-与-skill-的底层架构演进" aria-label="Permalink to &quot;剥开大模型的“全能”外衣：Function Call、MCP 与 Skill 的底层架构演进&quot;">​</a></h2><p>在当今的 AI 开发圈，让大模型“长出手脚”去操作外部系统已经成为标配。无论是简单的查天气，还是复杂的自动化代码生成，背后都离不开工具调用。但随着应用复杂度的提升，我们经常会听到 Function Call、MCP（Model Context Protocol）以及 Agent Skill 这几个概念混杂在一起。</p><p>在过去二十多年的软件研发与架构演进中，我们明白一个道理：<strong>任何新技术的引入，本质上都是在寻找更优雅的解耦与抽象方式。</strong> 大模型的工具调用也不例外。</p><p>本文将从系统架构的视角，带你彻底厘清这三者的底层逻辑、异同点以及适用场景。</p><h2 id="一个核心错觉-大模型在-执行-代码" tabindex="-1">一个核心错觉：大模型在“执行”代码 <a class="header-anchor" href="#一个核心错觉-大模型在-执行-代码" aria-label="Permalink to &quot;一个核心错觉：大模型在“执行”代码&quot;">​</a></h2><p>在深入对比之前，必须先纠正一个常见的直觉偏差：<strong>大模型绝对不会自己去实际执行网络请求或运行本地代码。</strong></p><p>大模型是一个纯粹的文本推断引擎。无论是哪种调用机制，在 LLM 自身的视角里，它永远只做两件事：</p><ol><li><strong>看说明书</strong>（读取 Prompt 里的工具定义）。</li><li><strong>输出结构化指令</strong>（吐出带有参数的 JSON 字符串）。</li></ol><p>真正去查数据库、调用 FastAPI 接口或者运行本地脚本的，永远是包裹着大模型的<strong>宿主运行环境（Host/Runtime）</strong>。Function Call、MCP 和 Skill 的区别，并不在模型内部，而是<strong>宿主环境的工程架构设计、系统解耦程度以及业务逻辑的厚度</strong>。</p><h2 id="_1-原语层-function-call-——-大模型的基础-汇编指令" tabindex="-1">1. 原语层：Function Call —— 大模型的基础“汇编指令” <a class="header-anchor" href="#_1-原语层-function-call-——-大模型的基础-汇编指令" aria-label="Permalink to &quot;1. 原语层：Function Call —— 大模型的基础“汇编指令”&quot;">​</a></h2><p>Function Call 是 OpenAI 最先提出并被各大模型广泛支持的底层机制。在这一层，你的应用代码和工具函数往往是强耦合的。可以把它看作是单体架构下最直接的本地函数调用。</p><p><strong>运行机制：</strong> 宿主应用把可用的函数（名称、描述、入参结构）喂给大模型；大模型如果认为需要调用，就中断文本生成，返回一段 JSON 格式的指令；宿主代码拦截到指令，在本地执行对应的 Python 函数后，把结果再次塞回给模型，完成闭环。</p>',12)),t(B,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20User%20as%20%E7%94%A8%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20App%20as%20%E5%AE%BF%E4%B8%BB%E7%8E%AF%E5%A2%83%2F%E4%B8%9A%E5%8A%A1%E4%BB%A3%E7%A0%81%3Cbr%3E(Agent%2FApp)%0A%20%20%20%20participant%20LLM%20as%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%E6%8E%A5%E5%8F%A3%3Cbr%3E(LLM%20API)%0A%20%20%20%20participant%20Tool%20as%20%E5%A4%96%E9%83%A8%E5%87%BD%E6%95%B0%2F%E6%9C%AC%E5%9C%B0%E8%84%9A%E6%9C%AC%3Cbr%3E(Function)%0A%0A%20%20%20%20User-%3E%3EApp%3A%201.%20%E5%8F%91%E9%80%81%E6%8F%90%E9%97%AE%EF%BC%88%E4%BE%8B%EF%BC%9A%22%E8%8B%B9%E6%9E%9C%E8%82%A1%E7%A5%A8%E7%8E%B0%E5%9C%A8%E5%A4%9A%E5%B0%91%E9%92%B1%EF%BC%9F%22%EF%BC%89%0A%20%20%20%20App-%3E%3ELLM%3A%202.%20%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E9%97%AE%20%2B%20%E5%8F%AF%E7%94%A8%E5%87%BD%E6%95%B0%E5%AE%9A%E4%B9%89%20(Tools%20Schema)%0A%20%20%20%20Note%20right%20of%20LLM%3A%20%E5%86%85%E9%83%A8%E6%8E%A8%E7%90%86%EF%BC%9A%3Cbr%2F%3E%E5%88%A4%E6%96%AD%E8%AF%A5%E9%97%AE%E9%A2%98%E9%9C%80%E8%A6%81%E8%B0%83%E7%94%A8%E5%87%BD%E6%95%B0%EF%BC%8C%3Cbr%2F%3E%E4%BB%8E%E4%B8%8A%E4%B8%8B%E6%96%87%E4%B8%AD%E6%8F%90%E5%8F%96%E5%8F%82%E6%95%B0%20%22AAPL%22%0A%20%20%20%20LLM--%3E%3EApp%3A%203.%20%E8%BF%94%E5%9B%9E%E4%B8%AD%E6%96%AD%E6%8C%87%E4%BB%A4%20(Tool_Call)%EF%BC%9A%3Cbr%2F%3E%7B%22name%22%3A%20%22get_stock%22%2C%20%22args%22%3A%20%7B%22symbol%22%3A%20%22AAPL%22%7D%7D%0A%20%20%20%20Note%20left%20of%20App%3A%20%E5%AE%BF%E4%B8%BB%E4%BB%A3%E7%A0%81%E6%8B%A6%E6%88%AA%E5%88%B0%20Tool_Call%EF%BC%8C%3Cbr%2F%3E%E6%9A%82%E5%81%9C%E4%B8%8E%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%9A%84%E5%AF%B9%E8%AF%9D%0A%20%20%20%20App-%3E%3ETool%3A%204.%20%E6%9C%AC%E5%9C%B0%E4%BB%A3%E7%A0%81%E6%89%A7%E8%A1%8C%E5%AE%9E%E9%99%85%E8%B0%83%E7%94%A8%EF%BC%9A%3Cbr%2F%3Eget_stock(%22AAPL%22)%0A%20%20%20%20Tool--%3E%3EApp%3A%205.%20%E8%BF%94%E5%9B%9E%E7%9C%9F%E5%AE%9E%E4%B8%9A%E5%8A%A1%E6%95%B0%E6%8D%AE%EF%BC%9A%3Cbr%2F%3E%7B%22price%22%3A%20150%7D%0A%20%20%20%20App-%3E%3ELLM%3A%206.%20%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E8%BF%BD%E5%8A%A0%20Tool_Message%3Cbr%2F%3E%EF%BC%88%E6%90%BA%E5%B8%A6%E5%88%9A%E5%88%9A%E6%8B%BF%E5%88%B0%E7%9A%84%20%7B%22price%22%3A%20150%7D%EF%BC%89%0A%20%20%20%20Note%20right%20of%20LLM%3A%20%E5%86%85%E9%83%A8%E6%8E%A8%E7%90%86%EF%BC%9A%3Cbr%2F%3E%E8%AF%BB%E5%8F%96%E8%A1%A5%E5%85%85%E8%BF%9B%E6%9D%A5%E7%9A%84%E7%9C%9F%E5%AE%9E%E6%95%B0%E6%8D%AE%EF%BC%8C%3Cbr%2F%3E%E8%9E%8D%E5%90%88%E4%B8%8A%E4%B8%8B%E6%96%87%E7%94%9F%E6%88%90%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%0A%20%20%20%20LLM--%3E%3EApp%3A%207.%20%E8%BF%94%E5%9B%9E%E6%9C%80%E7%BB%88%E6%96%87%E6%9C%AC%EF%BC%9A%3Cbr%2F%3E%22%E8%8B%B9%E6%9E%9C%E7%9B%AE%E5%89%8D%E7%9A%84%E8%82%A1%E4%BB%B7%E6%98%AF%20150%20%E7%BE%8E%E5%85%83%E3%80%82%22%0A%20%20%20%20App--%3E%3EUser%3A%208.%20%E5%B1%95%E7%A4%BA%E6%9C%80%E7%BB%88%E7%AD%94%E5%A4%8D%0A%0A"}),E[1]||(E[1]=A('<p><strong>定位：</strong> 最底层的能力原语。适合轻量级的工具集成，缺点是工具的扩展和跨语言/跨机器调用不够标准化。</p><h2 id="_2-协议层-mcp-model-context-protocol-——-工具接入的微服务化" tabindex="-1">2. 协议层：MCP (Model Context Protocol) —— 工具接入的微服务化 <a class="header-anchor" href="#_2-协议层-mcp-model-context-protocol-——-工具接入的微服务化" aria-label="Permalink to &quot;2. 协议层：MCP (Model Context Protocol) —— 工具接入的微服务化&quot;">​</a></h2><p>当你的 AI 助手需要接入本地 IDE、知识库、外部数据库等几十种工具时，让宿主应用把这些工具的代码全写在一起显然违背了高内聚低耦合的原则。</p><p>MCP 应运而生。它是 Anthropic 等主导的<strong>标准通信协议</strong>。在 MCP 架构下，宿主变成了 <strong>MCP Client</strong>，而工具被抽离成了独立的 <strong>MCP Server</strong>。这就好比将单体应用拆分成了微服务，通过标准的 JSON-RPC 进行跨进程甚至跨机器的交互。</p>',4)),t(B,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20User%20as%20%E7%94%A8%E6%88%B7%0A%20%20%20%20participant%20Client%20as%20%E5%AE%BF%E4%B8%BB%E7%B3%BB%E7%BB%9F%3Cbr%3E(Agent%20%2F%20MCP%20Client)%0A%20%20%20%20participant%20LLM%20as%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%0A%20%20%20%20participant%20MCPServer%20as%20%E5%A4%96%E9%83%A8%E6%95%B0%E6%8D%AE%E6%BA%90%2F%E5%B7%A5%E5%85%B7%3Cbr%3E(MCP%20Server)%0A%0A%20%20%20%20User-%3E%3EClient%3A%20%22%E6%9F%A5%E4%B8%80%E4%B8%8B%E6%9C%AC%E5%9C%B0%E7%9A%84%E5%BC%80%E5%8F%91%E6%96%87%E6%A1%A3%E9%87%8C%E5%85%B3%E4%BA%8E%20API%20%E7%9A%84%E5%AE%9A%E4%B9%89%22%0A%20%20%20%20Note%20over%20Client%2CMCPServer%3A%201.%20%E5%90%AF%E5%8A%A8%E6%97%B6%EF%BC%8CClient%20%E9%80%9A%E8%BF%87%E5%8D%8F%E8%AE%AE%E5%90%91%20Server%20%E5%8F%91%E7%8E%B0%E5%B9%B6%E6%8B%89%E5%8F%96%E5%8F%AF%E7%94%A8%E5%B7%A5%E5%85%B7%E9%9B%86%0A%20%20%20%20Client-%3E%3ELLM%3A%20%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E9%97%AE%20%2B%20%E6%A0%87%E5%87%86%E5%8C%96%E8%BD%AC%E6%8D%A2%E5%90%8E%E7%9A%84%20Tools%20Schema%0A%20%20%20%20LLM--%3E%3EClient%3A%20%E8%BF%94%E5%9B%9E%20Tool_Call%20(JSON%20%E6%8C%87%E4%BB%A4)%0A%20%20%20%20Note%20left%20of%20Client%3A%20Client%20%E6%8B%A6%E6%88%AA%E6%8C%87%E4%BB%A4%EF%BC%8C%E5%8F%91%E7%8E%B0%E9%9C%80%E8%A6%81%E8%B0%83%E7%94%A8%20MCP%20%E8%B5%84%E6%BA%90%0A%20%20%20%20Client-%3E%3EMCPServer%3A%20%E6%8C%89%E7%85%A7%20JSON-RPC%20%E5%8D%8F%E8%AE%AE%E5%8F%91%E9%80%81%E6%A0%87%E5%87%86%E5%8C%96%E8%AF%B7%E6%B1%82%3Cbr%3E%7B%22method%22%3A%20%22tools%2Fcall%22%2C%20%22params%22%3A%20%7B...%7D%7D%0A%20%20%20%20MCPServer--%3E%3EClient%3A%20%E8%BF%94%E5%9B%9E%E6%A0%87%E5%87%86%E5%8C%96%E7%BB%93%E6%9E%9C%E6%A0%BC%E5%BC%8F%0A%20%20%20%20Client-%3E%3ELLM%3A%20%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E8%BF%BD%E5%8A%A0%E5%B7%A5%E5%85%B7%E6%89%A7%E8%A1%8C%E7%BB%93%E6%9E%9C%0A%20%20%20%20LLM--%3E%3EClient%3A%20%E8%BF%94%E5%9B%9E%E6%9C%80%E7%BB%88%E6%96%87%E6%9C%AC%0A%20%20%20%20Client--%3E%3EUser%3A%20%E5%B1%95%E7%A4%BA%E7%AD%94%E5%A4%8D%0A%0A"}),E[2]||(E[2]=A('<p><strong>定位：</strong> 标准化协议层。解决了“工具发现”与“跨进程通信”的问题，让大模型能以极其统一的姿态连接各种异构数据源和执行环境。</p><h2 id="_3-业务层-skill-技能-——-高内聚的复杂工作流与状态机" tabindex="-1">3. 业务层：Skill (技能) —— 高内聚的复杂工作流与状态机 <a class="header-anchor" href="#_3-业务层-skill-技能-——-高内聚的复杂工作流与状态机" aria-label="Permalink to &quot;3. 业务层：Skill (技能) —— 高内聚的复杂工作流与状态机&quot;">​</a></h2><p>在实际的重度研发场景中，比如多 Agent 协作系统，我们极少让主控大模型去直接调用细粒度的基础 API（比如“连接数据库”、“执行 SQL”、“处理时间戳”）。这会导致主模型的 Prompt 极度臃肿，且非常容易发生“幻觉”和偏航。</p><p>这就引出了 <strong>Skill（技能）</strong> 的概念。Skill 是在工程架构上做的<strong>业务级封装</strong>。</p><p>例如，你需要构建一个量化交易的 Agent：你不会把具体的 Level-2 盘口数据解析 API 直接暴露给主模型，而是封装一个名为 <code>run_qmt_backtest_skill</code> 的高级技能。主模型只需要做高层的决策并发起调用，而 Skill 内部隐藏了一个完整的状态机逻辑，可能会自行调用 Python 脚本、驱动专用的底层框架执行回测、生成图表，最后只把核心结果摘要交还给主模型。</p>',5)),t(B,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20User%20as%20%E7%94%A8%E6%88%B7%0A%20%20%20%20participant%20Agent%20as%20%E4%B8%BB%E6%8E%A7%E8%B0%83%E5%BA%A6%20Agent%0A%20%20%20%20participant%20LLM%20as%20%E4%B8%BB%E5%A4%A7%E6%A8%A1%E5%9E%8B%0A%20%20%20%20participant%20SkillEngine%20as%20%E6%8A%80%E8%83%BD%E6%89%A7%E8%A1%8C%E5%BC%95%E6%93%8E%3Cbr%3E(Skill%20Engine)%0A%20%20%20%20participant%20Worker%20as%20%E6%8A%80%E8%83%BD%E5%86%85%E9%83%A8%E9%80%BB%E8%BE%91%3Cbr%3E(%E5%A6%82%EF%BC%9AQMT%20%E7%AD%96%E7%95%A5%E5%9B%9E%E6%B5%8B%20%2F%20%E5%AD%90%E6%A8%A1%E5%9E%8B)%0A%0A%20%20%20%20User-%3E%3EAgent%3A%20%22%E5%B8%AE%E6%88%91%E7%94%A8%E5%88%9A%E6%89%8D%E7%9A%84%E5%9D%87%E7%BA%BF%E7%AD%96%E7%95%A5%E8%B7%91%E4%B8%80%E4%B8%8B%E5%9B%9E%E6%B5%8B%22%0A%20%20%20%20Agent-%3E%3ELLM%3A%20%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E9%97%AE%20%2B%20%E9%AB%98%E9%98%B6%20Skill%20%E7%9A%84%E6%8F%8F%E8%BF%B0%0A%20%20%20%20LLM--%3E%3EAgent%3A%20%E8%BF%94%E5%9B%9E%E6%8C%87%E4%BB%A4%EF%BC%9A%E8%B0%83%E7%94%A8%20%22Backtest_Skill%22%20%E5%8F%8A%E5%85%B6%E5%8F%82%E6%95%B0%0A%20%20%20%20Note%20left%20of%20Agent%3A%20%E6%8B%A6%E6%88%AA%E5%88%B0%E6%8C%87%E4%BB%A4%EF%BC%8C%E4%BA%A4%E7%94%B1%E4%B8%93%E9%97%A8%E7%9A%84%E6%8A%80%E8%83%BD%E5%BC%95%E6%93%8E%E5%A4%84%E7%90%86%0A%20%20%20%20Agent-%3E%3ESkillEngine%3A%20%E8%A7%A6%E5%8F%91%E5%A4%8D%E6%9D%82%E7%9A%84%20Skill%20%E5%AE%9E%E4%BE%8B%0A%20%20%20%20Note%20over%20SkillEngine%2CWorker%3A%20Skill%20%E5%86%85%E9%83%A8%E5%B9%B6%E9%9D%9E%E7%AE%80%E5%8D%95%E8%AF%B7%E6%B1%82%EF%BC%8C%E8%80%8C%E6%98%AF%E5%A4%9A%E6%AD%A5%E6%89%A7%E8%A1%8C%E6%B5%81%3Cbr%2F%3E%E7%94%9A%E8%87%B3%E5%8C%85%E5%90%AB%E7%8B%AC%E7%AB%8B%E7%9A%84%E8%BF%90%E8%A1%8C%E6%97%B6%E7%8E%AF%E5%A2%83%E9%9A%94%E7%A6%BB%0A%20%20%20%20SkillEngine-%3E%3EWorker%3A%20%E5%90%AF%E5%8A%A8%E6%9C%AC%E5%9C%B0%E5%9B%9E%E6%B5%8B%E7%8E%AF%E5%A2%83%EF%BC%8C%E5%8A%A0%E8%BD%BD%E5%8E%86%E5%8F%B2%20Level-2%20%E6%95%B0%E6%8D%AE%0A%20%20%20%20Worker--%3E%3ESkillEngine%3A%20%E8%BF%90%E8%A1%8C%E7%BB%93%E6%9D%9F%EF%BC%8C%E7%94%9F%E6%88%90%E5%9B%BE%E8%A1%A8%E5%92%8C%E6%80%A7%E8%83%BD%E6%8C%87%E6%A0%87%0A%20%20%20%20SkillEngine--%3E%3EAgent%3A%20%E8%81%9A%E5%90%88%E7%BB%93%E6%9E%9C%EF%BC%9A%7B%22%E8%83%9C%E7%8E%87%22%3A%20%2265%25%22%2C%20%22%E5%9B%BE%E8%A1%A8%E8%B7%AF%E5%BE%84%22%3A%20%22%2Ftmp%2F1.png%22%7D%0A%20%20%20%20Agent-%3E%3ELLM%3A%20%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%AF%B7%E6%B1%82%EF%BC%9A%E5%B0%86%E6%80%BB%E7%BB%93%E6%80%A7%E7%9A%84%E4%B8%9A%E5%8A%A1%E7%BB%93%E6%9E%9C%E5%96%82%E7%BB%99%E4%B8%BB%E6%A8%A1%E5%9E%8B%0A%20%20%20%20LLM--%3E%3EAgent%3A%20%E8%BF%94%E5%9B%9E%E6%B7%B1%E5%BA%A6%E5%88%86%E6%9E%90%E7%9A%84%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%0A%20%20%20%20Agent--%3E%3EUser%3A%20%E5%B1%95%E7%A4%BA%E6%9C%80%E7%BB%88%E5%88%86%E6%9E%90%E6%8A%A5%E5%91%8A%E5%8F%8A%E5%9B%BE%E8%A1%A8%0A%0A"}),E[3]||(E[3]=A('<p><strong>定位：</strong> 架构设计上的业务抽象层。用于任务拆解和系统隔离，保护主模型免受底层琐碎执行流的干扰。</p><hr><h2 id="总结-同源而殊途" tabindex="-1">总结：同源而殊途 <a class="header-anchor" href="#总结-同源而殊途" aria-label="Permalink to &quot;总结：同源而殊途&quot;">​</a></h2><p>最后，我们可以用一张表来总结这三者的异同点：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>Function Call</th><th>MCP (Model Context Protocol)</th><th>Skill (技能)</th></tr></thead><tbody><tr><td><strong>在大模型眼里的形态</strong></td><td>一段工具描述 + 输出 JSON 指令</td><td>一段工具描述 + 输出 JSON 指令</td><td>一段工具描述 + 输出 JSON 指令</td></tr><tr><td><strong>工程架构定位</strong></td><td>底层能力原语</td><td>标准化通信协议</td><td>业务逻辑封装与抽象层</td></tr><tr><td><strong>宿主侧的复杂度</strong></td><td>低（单体调用，通常同语言、同进程）</td><td>中（基于 JSON-RPC 的 C/S 架构，跨进程/机器）</td><td>高（内部可能包含子 Agent、状态机或复杂脚本引擎）</td></tr><tr><td><strong>核心解决的问题</strong></td><td>让大模型具备结构化输出能力</td><td>解决异构工具的标准化接入与发现</td><td>解决复杂任务拆解，防止大模型上下文污染</td></tr><tr><td><strong>类比传统软件开发</strong></td><td><code>def</code> 本地函数调用</td><td>HTTP / RESTful API</td><td>业务模块 / 黑盒微服务系统</td></tr></tbody></table><p>从 Function Call 到 MCP 再到 Agent Skill，大模型本身的运作机制并没有发生本质的改变。真正进化的，是我们作为开发者，在面对日益复杂的 AI 应用需求时，所采用的<strong>系统级解耦与抽象思维</strong>。理解了这一点，就能在架构选型时有的放矢，游刃有余。</p>',6))])}const g=e(n,[["render",r]]);export{d as __pageData,g as default};
